// Score a submitted lead description and suggest a sales-rep next step.
// Sensitive personal data is masked before model calls. Uncertain or failed processing goes to human review.
// This workflow only returns a recommendation; it never updates records or contacts leads.

budget { tokens: 5000  calls: 4 }

agent PrivacyFilter {
    model: "gpt-6-luna"
    prompt: "privacy_filter"
    temperature: 0.1
    guard { pii: mask }
    output_schema: { brief: string, evidence: enum["SUFFICIENT", "INSUFFICIENT"] }
}

agent SalesAdvisor {
    model: "gpt-6-luna"
    prompt: "sales_advisor"
    temperature: 0.2
    output_schema: { next_step: string }
}

intentclassifier LeadTemperature {
    model: "gpt-6-luna"
    samples: 3
    choose kind: hot | warm | cold | insufficient_evidence
    ask kind: "Using only this redacted summary, choose hot, warm, cold, or insufficient_evidence. Use insufficient_evidence when reliable sales qualification evidence is lacking."
    confidence at least 0.8 else escalate
}

workflow Main(qz_submission_blob) {
    alt (qz_submission_blob == "") {
        human_prompt "SalesReviewer: The submitted lead description is empty. Please review it; no score or recommendation was generated." -> qz_human_receipt
        return { status: "HUMAN_REVIEW", detail: "Empty description. Reviewer response: {qz_human_receipt}" }
    }

    delegate "Create a brief, sales-relevant summary of this submitted description. Exclude sensitive personal data and do not infer missing facts.\n\nSubmitted description:\n{qz_submission_blob}" to PrivacyFilter -> qz_masked_brief expecting {
        brief: string,
        evidence: enum["SUFFICIENT", "INSUFFICIENT"]
    } retry 1 backoff 2s timeout 30s on_failure {
        human_prompt "SalesReviewer: Redaction or summarization failed. Please review the lead description. The original description was not scored." -> qz_human_receipt
        return { status: "HUMAN_REVIEW", detail: "Redaction or summarization failed. Reviewer response: {qz_human_receipt}" }
    }

    alt (qz_masked_brief.evidence == "INSUFFICIENT") {
        human_prompt "SalesReviewer: The redacted summary does not contain enough reliable evidence to score this lead. Please review it; no temperature or next step was generated." -> qz_human_receipt
        return { status: "HUMAN_REVIEW", detail: "Insufficient evidence after redaction. Reviewer response: {qz_human_receipt}" }
    }

    set qz_scoring_text = "{qz_masked_brief.brief}"

    intentclassify LeadTemperature on qz_scoring_text -> qz_temperature_record retry 1 backoff 2s timeout 30s on_failure {
        human_prompt "SalesReviewer: Lead classification failed or was uncertain. Please review the redacted summary; no guessed temperature or next step was generated." -> qz_human_receipt
        return { status: "HUMAN_REVIEW", detail: "Classification failed. Reviewer response: {qz_human_receipt}" }
    }

    alt (qz_temperature_record.kind == "insufficient_evidence") {
        human_prompt "SalesReviewer: The classifier found insufficient evidence for a reliable hot, warm, or cold score. Please review the redacted summary; no next step was generated." -> qz_human_receipt
        return { status: "HUMAN_REVIEW", detail: "Insufficient classification evidence. Reviewer response: {qz_human_receipt}" }
    }

    alt (qz_temperature_record.kind == "unsure") {
        human_prompt "SalesReviewer: The classifier was not confident enough to assign a reliable temperature. Please review the redacted summary; no guessed temperature or next step was generated." -> qz_human_receipt
        return { status: "HUMAN_REVIEW", detail: "Uncertain classification. Reviewer response: {qz_human_receipt}" }
    }

    delegate "Suggest one practical next step for a sales rep based only on this redacted summary and the classifier's temperature. Do not change the temperature or invent evidence.\n\nTemperature: {qz_temperature_record.kind}\nRedacted summary:\n{qz_masked_brief.brief}" to SalesAdvisor -> qz_guidance_packet expecting {
        next_step: string
    } retry 1 backoff 2s timeout 30s on_failure {
        human_prompt "SalesReviewer: A safe, structured next-step recommendation could not be produced. Please review the redacted summary; no recommendation was returned." -> qz_human_receipt
        return { status: "HUMAN_REVIEW", detail: "Next-step generation failed. Reviewer response: {qz_human_receipt}" }
    }

    return { status: "RECOMMENDATION", temperature: "{qz_temperature_record.kind}", next_step: "{qz_guidance_packet.next_step}" }
}
