    alt (qz_submission_blob == "") {
        human_prompt "SalesReviewer: The submitted lead description is empty. Please review it; no score or recommendation was generated." -> qz_human_receipt
        return { status: "HUMAN_REVIEW", detail: "Empty description. Reviewer response: {qz_human_receipt}" }
    }

    delegate "Create a brief, sales-relevant summary of this submitted description. Exclude sensitive personal data and do not infer missing facts.\n\nSubmitted description:\n{qz_submission_blob}" to PrivacyFilter -> qz_masked_brief expecting {
        brief: string,
        evidence: enum["SUFFICIENT", "INSUFFICIENT"]
